package ganymedes01.etfuturum;

import java.util.Random;
import net.minecraft.block.*;
import net.minecraft.block.properties.IProperty;
import net.minecraft.block.state.IBlockState;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.item.*;
import net.minecraft.util.*;
import net.minecraft.util.math.BlockPos;
import net.minecraft.world.World;

/** One native oxidation and waxing path covers blocks, shapes, doors, bulbs and inventories. */
public final class CopperAging {
    private CopperAging() { }
    static boolean copper(Block block){if(block.getRegistryName()==null||!block.getRegistryName().getNamespace().equals(UAB.ID))return false;if(block.getRegistryName().getPath().equals("copper_ore"))return false;String feature=Content.FEATURE.get(block.getRegistryName().getPath());return CopperAge.fixture(block)||"blocksitems.enableCopper".equals(feature)||"content.decorative_copper".equals(feature)||"content.copper_chests".equals(feature)||"content.copper_golem_statues".equals(feature);}
    static int stage(Block block){String name=block.getRegistryName().getPath();return name.contains("oxidized_")?3:name.contains("weathered_")?2:name.contains("exposed_")?1:0;}
    static boolean waxed(Block block){return block.getRegistryName().getPath().startsWith("waxed_");}
    private static Block variant(Block block,int stage,boolean waxed){String name=block.getRegistryName().getPath().replaceFirst("^waxed_","").replaceFirst("^(exposed_|weathered_|oxidized_)","");if(name.equals("copper"))name="copper_block";if(stage>0&&name.equals("copper_block"))name="copper";return Content.BLOCKS.get((waxed?"waxed_":"")+new String[]{"","exposed_","weathered_","oxidized_"}[stage]+name);}
    @SuppressWarnings({"unchecked","rawtypes"}) static IBlockState properties(IBlockState old,Block block){IBlockState state=block.getDefaultState();for(IProperty property:old.getPropertyKeys()){IProperty target=block.getBlockState().getProperty(property.getName());if(target!=null){com.google.common.base.Optional value=target.parseValue(property.getName(old.getValue(property)));if(value.isPresent())state=state.withProperty(target,(Comparable)value.get());}}return state;}
    static void replace(World world,BlockPos pos,IBlockState old,Block block){if(block==null||block==old.getBlock())return;if(old.getBlock() instanceof BlockDoor){BlockPos lower=old.getValue(BlockDoor.HALF)==BlockDoor.EnumDoorHalf.UPPER?pos.down():pos;IBlockState base=world.getBlockState(lower),upper=world.getBlockState(lower.up());if(base.getBlock()!=old.getBlock()||upper.getBlock()!=old.getBlock())return;world.setBlockState(lower,properties(base,block),2);world.setBlockState(lower.up(),properties(upper,block),2);world.notifyNeighborsOfStateChange(lower,block,false);world.notifyNeighborsOfStateChange(lower.up(),block,false);}else {net.minecraft.tileentity.TileEntity previous=world.getTileEntity(pos);net.minecraft.nbt.NBTTagCompound saved=previous instanceof LightningRodTile?previous.writeToNBT(new net.minecraft.nbt.NBTTagCompound()):null;world.setBlockState(pos,properties(old,block),3);if(saved!=null&&world.getTileEntity(pos) instanceof LightningRodTile){world.getTileEntity(pos).readFromNBT(saved);world.getTileEntity(pos).markDirty();}if(block instanceof LightningRod&&old.getValue(LightningRod.POWERED)){net.minecraft.tileentity.TileEntity tile=world.getTileEntity(pos);world.scheduleUpdate(pos,block,tile instanceof LightningRodTile?Math.max(1,((LightningRodTile)tile).remaining()):8);}}}
    static void tick(World world,BlockPos pos,IBlockState state,Random random){Block block=state.getBlock();if(!copper(block)||waxed(block)||stage(block)==3||state.getPropertyKeys().contains(BlockDoor.HALF)&&state.getValue(BlockDoor.HALF)==BlockDoor.EnumDoorHalf.UPPER||random.nextFloat()>=.05688889F||!world.isAreaLoaded(pos,4))return;int older=0,total=0,current=stage(block);for(BlockPos nearby:BlockPos.getAllInBox(pos.add(-4,-4,-4),pos.add(4,4,4))){int distance=Math.abs(nearby.getX()-pos.getX())+Math.abs(nearby.getY()-pos.getY())+Math.abs(nearby.getZ()-pos.getZ());if(distance==0||distance>4)continue;Block other=world.getBlockState(nearby).getBlock();if(!copper(other))continue;if(stage(other)<current)return;if(stage(other)>current)older++;total++;}float ratio=(older+1F)/(total+1F);if(random.nextFloat()<ratio*ratio*(current==0?.75F:1))replace(world,pos,state,variant(block,current+1,false));}
    static boolean use(World world,BlockPos pos,IBlockState state,EntityPlayer player,EnumHand hand,EnumFacing face){Block block=state.getBlock();if(!copper(block))return false;ItemStack held=player.getHeldItem(hand);boolean wax=held.getItem()==Content.item("honeycomb")&&Content.available("honeycomb")&&!waxed(block),scrape=held.getItem() instanceof ItemAxe&&(waxed(block)||stage(block)>0);if(!wax&&!scrape||!player.canPlayerEdit(pos,face,held))return false;Block next=variant(block,scrape&&!waxed(block)?stage(block)-1:stage(block),wax);if(next==null)return false;if(!world.isRemote){replace(world,pos,state,next);if(!player.capabilities.isCreativeMode){if(wax)held.shrink(1);else held.damageItem(1,player);}world.playEvent(wax?2005:2001,pos,wax?0:Block.getStateId(state));}return true;}
    public static void lightning(World world,BlockPos pos){for(BlockPos near:BlockPos.getAllInBox(pos.add(-1,-1,-1),pos.add(1,1,1))){if(!world.isBlockLoaded(near))continue;IBlockState state=world.getBlockState(near);if(copper(state.getBlock())&&!waxed(state.getBlock()))replace(world,near,state,variant(state.getBlock(),0,false));}}
}
